#!/usr/bin/env python3
"""Report current, fully executed native front-end/replay/persistence gates."""
from pathlib import Path
import base64,hashlib,html,json,re
R=Path(__file__).resolve().parents[1];sha=hashlib.sha256((R/'rom/hexgl.j64').read_bytes()).hexdigest()
suites={name:json.loads((R/path).read_text()) for name,path in [('Core','test-results/summary.json'),('Desktop','test-results/gui/summary.json'),('HUD','test-results/hud-summary.json'),('Front end / replay / saves','test-results/frontend-summary.json'),('Dynamics / camera / effects','test-results/dynamics-summary.json'),('Materials / sky / stereo','test-results/material-summary.json'),('Dedicated fall / pause','test-results/fall-summary.json'),('Original stereo / audio events','test-results/original-audio-summary.json')]}
assert all(s['status']=='PASS' and s['rom_sha256']==sha for s in suites.values())
pa=json.loads((R/'docs/particles-audio-additional-checks.json').read_text())
assert pa['status']=='PASS' and pa['rom_sha256']==sha
probe=json.loads((R/'test-results/native-fx-probe/summary.json').read_text())
assert probe['status']=='PASS' and probe['rom_sha256']==sha
assert probe['production_depth_source_sha256']==hashlib.sha256((R/'src/fx_depth.inc').read_bytes()).hexdigest()

clean=json.loads((R/'docs/dynamics-clean-rebuild.json').read_text())
assert clean['status']=='PASS' and clean['rom_sha256']==sha
extra=json.loads((R/'docs/dynamics-additional-checks.json').read_text())
assert extra['status']=='PASS' and extra['rom_sha256']==sha
material_extra=json.loads((R/'docs/materials-additional-checks.json').read_text())
assert material_extra['status']=='PASS' and material_extra['rom_sha256']==sha
units=(R/'test-results/unit-tests.log').read_text();assert '\nOK' in units;n=re.search(r'Ran (\d+) tests',units)[1]
def picture(name,caption):
 p=R/'test-results'/name;b=base64.b64encode(p.read_bytes()).decode()
 return f'<figure><img src="data:image/png;base64,{b}" alt="{html.escape(caption)}"><figcaption>{html.escape(caption)}</figcaption></figure>'
shots=''.join([picture('materials-ntsc/frame_00580.png','Original normal/specular material lookup, native face lighting and camera-pitched sky'),picture('dynamics-drive-ntsc/frame_00575.png','Native chase-camera pitch and original booster glow at the ship stern'),picture('dynamics-drive-ntsc/frame_00620.png','Source-texture collision sparks/clouds projected from world-space particles'),picture('dynamics-route-ntsc/final.png','Original track geometry with bilinear hover and real ship/camera pitch'),picture('menu-ntsc/frame_00080.png','Original title/background; native menu with source Bebas Neue typography'),picture('menu-ntsc/frame_00180.png','Working controller help, rendered using the original font'),picture('replay-ntsc/frame_01040.png','Actual recorded run playing through native mesh and camera transforms'),picture('save-reboot-ntsc/final.png','Saved time loaded from cartridge EEPROM in a fresh emulator process')])
rows=''
for group,s in suites.items():
 for name,c in s['cases'].items():
  verdict=c.get('status','EXPECTED FAILURE' if 'expected_failure_detected' in c else 'PASS')
  desc=c.get('detected',c.get('expected_failure_detected',', '.join(c.get('checks',[]))))
  rows+=f'<tr><td>{html.escape(group+": "+name)}</td><td>{verdict}</td><td>{html.escape(desc)}</td></tr>'
front=suites['Front end / replay / saves'];save=front['cases']['save-ntsc']['record']
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HexGL Jaguar — perspective particles and original stereo</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#111b23;color:#e2edf1;font:16px/1.65 system-ui,sans-serif}}main{{max-width:1100px;margin:auto;padding:42px 24px}}h1{{font-size:48px;line-height:1.1}}h2{{margin-top:36px}}.tag{{font-size:12px;letter-spacing:2px;color:#70d8c6}}.lead{{font-size:21px;color:#b8cbd8}}.notice,.ok{{padding:18px 22px;background:#30291d;border-left:3px solid #e5ba65}}.ok{{background:#153a31;border-color:#70d8c6;margin-top:18px}}.shots{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}figure{{margin:0;background:#1c2c37}}img{{width:100%;display:block;image-rendering:pixelated}}figcaption{{padding:12px;font-size:13px}}table{{border-collapse:collapse;width:100%;font-size:13px}}td,th{{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #354852}}.scroll{{overflow:auto}}code,pre{{font:13px/1.6 ui-monospace,monospace;overflow-wrap:anywhere;white-space:pre-wrap}}pre{{padding:18px;background:#1c2c37}}footer{{margin-top:36px;padding-top:18px;border-top:1px solid #354852;color:#aebfcb;font-size:13px}}@media(max-width:650px){{h1{{font-size:36px}}.shots{{grid-template-columns:1fr}}}}</style>
<main><div class="tag">STANDALONE STOCK JAGUAR · NATIVE INTEGRATION · 2026-10-16</div><h1>Perspective particles.<br>Original stereo.</h1><p class="lead">Perspective-sized source sprites, real RGB alpha/additive composition, inherited motion and independently decoded original stereo, alongside native racing, materials, sky, replay and saves.</p>
<div class="notice"><strong>The request to implement everything is not finished.</strong> This build adds perspective RGB sprites, .7 velocity inheritance, conservative native depth queries and full-duration source-channel stereo IMA4 within the stock 6 MiB cartridge. Full angular/quaternion physics, cross-slope tilt, orbit/up-vector camera behavior, full emitter/color fidelity, moving shadows, bloom, shader-equivalent lighting, HRTF/gain fidelity and some presentation still need work. Online services are excluded by the agreed standalone-stock target—not represented by fake local network functions.</div>
<div class="ok"><strong>All eight current-ROM suites passed:</strong> 17 core scenarios, 7 stock desktop scenarios, 2 focused HUD runs, 10 front-end/replay/save scenarios, 4 focused dynamics/effects scenarios, 2 material/sky/stereo scenarios, 4 dedicated falling/pause scenarios, 2 original-stereo/event scenarios and {n} unit tests. Fault controls were rejected; all reports match this ROM hash.</div>
<h2>New in this build</h2><ul><li>Perspective-sized source sprite resampling and individual viewport clipping, with native RGB additive sparks/glow and alpha-over clouds.</li><li>Actual ship-motion velocity inheritance at approximately .7, retained bounded world-space lifetimes and pause.</li><li>Center-depth queries use real submitted triangle coordinates and vertex Z. A separate native GPU diagnostic ROM tests 12 query cases, including three real rejection results. Driving traces verify depth math, not observed occlusion events.</li><li>All five full-duration original left/right sources fit the original one-MiB audio slot as stereo IMA4; the DSP independently decodes both channels and retains source content.</li><li>Source-texel, alpha, RGB, perspective-size, actual TOM pixel, native triangle depth, and exact DSP-source sample proofs.</li></ul><p><code>docs/PARTICLES-AND-ORIGINAL-STEREO.md</code> documents source mapping, compressed-audio quality, memory, fixtures and remaining compromises. This is not per-fragment WebGL, HRTF, or full physics parity.</p><h2>Retained material and sky integration</h2><ul><li>Original normal/specular maps and six-face sky reflections converted to eight camera-dependent native material banks.</li><li>Actual scene-triangle sun visibility baked into face luminance, plus real booster-local scene-face illumination.</li><li>Zero-key ordered-alpha booster, double-sided banner and source-blue speed material.</li><li>Camera pitch and yaw drive a taller native sky panorama, with split blits at its seam.</li><li>Original-channel music/destruction without movement panning and spatially balanced wind/boost/collision, with distinct signed-saturating left/right I2S output.</li><li>Fixed falling displacement at longer frame steps; multiplication operands now respect Jaguar low-16-bit arithmetic.</li></ul><p>These are hardware adaptations, not shader/WebAudio equivalence. See <code>docs/MATERIALS-SKY-AND-STEREO.md</code> for source hashes, algorithms, memory layout and remaining fidelity gaps.</p><h2>Retained native dynamics</h2><ul><li>Actual lateral airbrake drift and decaying map-derived contact impulses.</li><li>Bilinear height-map hover, active-time falling/destruction and filtered terrain pitch on the original ship and booster meshes.</li><li>Vertical chase look-at rotation of real rendered vertices and normals. An independent oracle checks actual GPU-transformed and projected ship vertices.</li><li>Original spark/cloud textures in real world-space collision emitters: a bounded 16-slot pool, one-second lifetimes, fading and pause.</li><li>Original stern booster glow sprite controlled by speed and boost. The sprite is separate from the new coarse scene-face light; neither implements bloom.</li><li>Ship/camera pitch stored and interpolated in actual-run replay.</li></ul><p>Detailed source mapping, hardware adaptations and limits: <code>docs/DYNAMICS-AND-EFFECTS.md</code>. Particle rendering uses perspective-resampled source art, native RGB additive/alpha-over and a conservative center-depth policy, not a full WebGL pipeline. The sky now follows camera pitch as a cylindrical crop, not a fully rotated cubemap.</p><h2>Retained systems</h2><ul><li>Original <code>bg.jpg</code>, <code>title.png</code> and Bebas Neue font: native Start, Controls, Local Records, Credits, Replay and result presentation.</li><li>Controller-only menu navigation. A confirms; Up/Down select; Option returns to Start. Browser layout/settings/transitions are adapted, not reproduced exactly.</li><li>Genuine native run sampling and elapsed-field interpolation of position, heading, bank and camera. Pause, end hold and Option exit work; replay cannot save a score.</li><li>Real cartridge EEPROM serial transactions with two-slot journals, checksum/version validation, readback and bounded waits. Manual and autopilot best times remain separate.</li><li>Existing source-art gauges, countdown, split timing, ship/camera filters and black-screen gates retained.</li></ul>
<h2>Actual emulator captures</h2><div class="shots">{shots}</div><p>These are actual Virtual Jaguar output, not illustrative mockups. The menu art is converted from original files. Playback drives the real native mesh/camera; it does not play a video or the supplied static upstream replay.</p>
<h2>Persistence proof</h2><p>A complete native three-lap race wrote and verified nine EEPROM words. A separate emulator process reopened the same CRC-named cartridge EEPROM file and visibly displayed the same saved value. NTSC evidence: total {save['total_ms']} ms, best lap {save['lap_ms']} ms. PAL is independently tested with field-normalized milliseconds. Replay/menu navigation performs no score writes.</p><p>Additional EEPROM-format fault fixtures verify checksum rejection, incomplete-commit fallback, generation wrap and blank storage. They are fault-test inputs, not fabricated race evidence. No host tool patches game RAM.</p>
<h2>Replay limits</h2><p>The last run lives in RAM: 6,144 samples × 64 bytes plus two recorded angle bytes per sample, all ending before the framebuffer. A new countdown replaces it; power-off loses it. A full buffer safely retains a playable prefix. Native chase-camera coordinates are reproduced, not original THREE.js quaternion/orbit behavior. This is bounded native replay, not unlimited persistent recording.</p>
<h2>Executed validation</h2><div class="scroll"><table><tr><th>Scenario</th><th>Verdict</th><th>Checks / detected fault</th></tr>{rows}</table></div>
<h2>Clean rebuild</h2><p><code>docs/dynamics-clean-rebuild.json</code> and its build log document a separate fresh source build with full material/geometry/sky/audio regeneration producing an identical ROM, with additional NTSC/PAL boot, HUD, physics and actual-vertex checks.</p><h2>Build and play</h2><pre>make assets    # regenerate all original asset groups
make rom       # GPU/DSP/68000 build + cartridge checks
make test      # all native/core/UI/save/replay and stock GUI gates
make release   # gate, current report and source/ROM archive
virtualjaguar rom/hexgl.j64 --ntsc --gpu --dsp</pre><p>In a race: A/Up thrust, Left/Right steer, B/Down brake, C autopilot, Pause hold, Option reset/menu. Stock keyboard defaults include L=A, J=C, Z/C=steering, K=B, P=Pause, O=Option; S/X = menu Up/Down and L confirms (or use your configured controller).</p>
<h2>Artifact and source mapping</h2><pre>rom/hexgl.j64 — 6,291,456 bytes
SHA-256: {sha}</pre><p><code>docs/FRONTEND-REPLAY-SAVES.md</code> documents the native implementation and constraints.<br><code>docs/STOCK-JAGUAR-SCOPE.md</code> lists the remaining work.<br><code>assets/frontend.json</code> records original asset/font hashes.</p><footer>Physical Jaguar/EEPROM variants, automated Windows Virtual Jaguar 2.1.2 and remote CI remain untested. A compatible EEPROM-equipped cartridge or writable emulator save directory is required for persistence. Finite emulator tests do not guarantee every input sequence/configuration. Original file-specific licensing notices are preserved.</footer></main></html>'''
(R/'REPORT.html').write_text(page)
md=f'# Native particles, original stereo and retained systems: executed results\n\nROM SHA-256: `{sha}`\n\nEight suites: **PASS**. {n} unit tests: **PASS**.\n\n'
for name,s in suites.items():md+='## '+name+'\n\n```json\n'+json.dumps(s,indent=2)+'\n```\n\n'
md+='## Separate native GPU depth fixtures\n\n```json\n'+json.dumps(probe,indent=2)+'\n```\n\n'
md+='This does not complete every remaining port system. Physical hardware and remote CI remain untested.\n'
(R/'docs/TEST-RESULTS.md').write_text(md)
print(R/'REPORT.html')
